skin.css:
/* ---- the bar ------------------------------------------------------- */
.tm {
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 20px;
  box-sizing: border-box;
  max-width: min(94vw, 980px);
  padding: 8px 10px 8px 18px;
  border-radius: 999px;
  color: #fff;
  font-size: 13px;
  pointer-events: auto;

  /* glass */
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(18px) saturate(160%);
  -webkit-backdrop-filter: blur(18px) saturate(160%);
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}

.tm-brand {
  font-weight: 600;
  letter-spacing: 0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}

.tm-nav {
  display: flex;
  gap: 4px;
}

/* the hamburger and its checkbox exist only below the breakpoint */
.tm-toggle,
.tm-burger { display: none; }

/* ---- top-level items ----------------------------------------------- */
.tm-group { position: relative; }

.tm-btn {
  padding: 7px 14px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 0.15s ease-out;
}
.tm-btn:hover,
.tm-group:focus-within .tm-btn {
  background: rgba(255, 255, 255, 0.18);
}

/* ---- drop-down panels ---------------------------------------------- */
.tm-panel {
  position: absolute;
  top: calc(100% + 12px);
  left: 50%;
  transform: translateX(-50%) translateY(-6px);
  box-sizing: border-box;
  padding: 8px;
  border-radius: 16px;
  color: #fff;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.16s ease-out, transform 0.16s ease-out, visibility 0.16s;

  background: rgba(20, 22, 28, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(22px) saturate(160%);
  -webkit-backdrop-filter: blur(22px) saturate(160%);
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
}
.tm-group:hover .tm-panel,
.tm-group:focus-within .tm-panel {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

/* an invisible bridge so the pointer can cross the gap to the panel */
.tm-panel::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: -12px;
  height: 12px;
}

/* ---- scenes panel --------------------------------------------------- */
.tm-panel-scenes {
  display: grid;
  grid-template-columns: repeat(2, 150px);
  gap: 6px;
  max-height: 60vh;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}

.tm-scene {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 6px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 12px;
  text-align: left;
  cursor: pointer;
  transition: background-color 0.15s ease-out;
}
.tm-scene:hover { background: rgba(255, 255, 255, 0.14); }

.tm-scene-thumb {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.08);
}
.tm-scene-thumb[hidden] { display: none; }

.tm-scene-name {
  padding: 0 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tm-scene[data-tour-current] {
  background: var(--tour-accent, #634469);
  color: #fff;
}

/* ---- text panels ----------------------------------------------------- */
.tm-panel-text {
  width: 300px;
  padding: 16px 18px;
  font-size: 13px;
  line-height: 1.5;
}
.tm-panel-text h3 {
  margin: 0 0 6px;
  font-size: 13px;
  font-weight: 600;
}
.tm-panel-text p {
  margin: 0;
  color: rgba(255, 255, 255, 0.78);
}
.tm-panel-text code {
  padding: 1px 4px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.14);
  font-size: 12px;
}

/* ---- the info sidebar -------------------------------------------------
   One repeat of every scene, but only the room the visitor is in is drawn.
   A checkbox holds the open state; the pill and the × are both labels for
   it, so it opens and closes with no script. */
.ip-toggle { display: none; }

.ip-open {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 21;
  display: flex;
  align-items: center;
  gap: 9px;
  box-sizing: border-box;
  height: 40px;
  padding: 0 16px 0 8px;
  border-radius: 999px;
  color: #fff;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  pointer-events: auto;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.15s ease-out, opacity 0.2s ease-out,
              transform 0.2s ease-out, visibility 0.2s;

  /* glass */
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(18px) saturate(160%);
  -webkit-backdrop-filter: blur(18px) saturate(160%);
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}
.ip-open:hover { background: rgba(255, 255, 255, 0.20); }
.ip-open:active { transform: scale(0.97); }

/* the round "i" */
.ip-open-mark {
  display: grid;
  place-items: center;
  flex: none;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--tour-accent, #634469);
  font-size: 13px;
  font-weight: 700;
  font-style: italic;
  font-family: Georgia, "Times New Roman", serif;
  line-height: 1;
}

/* while the sidebar is open the pill gets out of the way */
.ip-toggle:checked ~ .ip-open {
  opacity: 0;
  visibility: hidden;
  transform: translateX(12px);
}

.ip {
  position: absolute;
  top: 16px;
  right: 16px;
  bottom: 16px;
  z-index: 22;
  box-sizing: border-box;
  width: min(360px, calc(100vw - 32px));
  padding: 22px 24px;
  border-radius: 20px;
  color: #fff;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  pointer-events: auto;

  opacity: 0;
  visibility: hidden;
  transform: translateX(16px);
  transition: opacity 0.22s ease-out, transform 0.22s ease-out, visibility 0.22s;

  /* glass */
  background: rgba(20, 22, 28, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(22px) saturate(160%);
  -webkit-backdrop-filter: blur(22px) saturate(160%);
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.44),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
}
.ip-toggle:checked ~ .ip {
  opacity: 1;
  visibility: visible;
  transform: translateX(0);
}

.ip-close {
  position: absolute;
  top: 14px;
  right: 14px;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.15s ease-out;
}
.ip-close:hover { background: rgba(255, 255, 255, 0.24); }
.ip-close::before,
.ip-close::after {
  content: "";
  position: absolute;
  width: 12px;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
}
.ip-close::before { transform: rotate(45deg); }
.ip-close::after { transform: rotate(-45deg); }

.ip-eyebrow {
  margin-bottom: 10px;
  padding-right: 34px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.55);
}

/* every scene but the one the visitor is standing in */
.ip-scene { display: none; }
.ip-scene[data-tour-current] { display: block; }

.ip-name {
  margin: 0 0 12px;
  font-size: 19px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: 0.01em;
}
.ip-name::after {
  content: "";
  display: block;
  width: 34px;
  height: 2px;
  margin-top: 12px;
  border-radius: 2px;
  background: var(--tour-accent, #634469);
}

.ip-text {
  margin: 0;
  font-size: 13.5px;
  line-height: 1.62;
  color: rgba(255, 255, 255, 0.80);
  white-space: pre-wrap;
}

/* ---- bottom nav ------------------------------------------------------ */
/* One repeat of every scene. Only three of them are ever drawn: the room
   the visitor is in (the label), the one before it and the one after it
   (the arrows). The rest stay hidden. */
.nb {
  position: absolute;
  bottom: calc(22px + env(safe-area-inset-bottom, 0px));
  left: 50%;
  transform: translateX(-50%);
  z-index: 20;
  box-sizing: border-box;
  max-width: calc(100vw - 24px);
  color: #fff;
  font-size: 13px;
  pointer-events: auto;

  /* glass */
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(18px) saturate(160%);
  -webkit-backdrop-filter: blur(18px) saturate(160%);
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}

.nb-track {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: min(380px, calc(100vw - 24px));
  height: 52px;
  padding: 0 56px;
}

/* every scene but the three we want */
.nb-item {
  display: none;
  min-width: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

/* the middle: the room the visitor is in */
.nb-item[data-tour-current] {
  display: block;
  max-width: 100%;
  pointer-events: none;
  cursor: default;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-align: center;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}
.nb-item[data-tour-current] .nb-name {
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* the arrows: the scene just before, and just after, the current one */
.nb-item:has(+ [data-tour-current]),
.nb-item[data-tour-current] + .nb-item {
  position: absolute;
  top: 50%;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  margin-top: -18px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  transition: background-color 0.15s ease-out, transform 0.15s ease-out;
}
.nb-item:has(+ [data-tour-current]) { left: 8px; }
.nb-item[data-tour-current] + .nb-item { right: 8px; }

.nb-item:has(+ [data-tour-current]):hover,
.nb-item[data-tour-current] + .nb-item:hover {
  background: rgba(255, 255, 255, 0.24);
}
.nb-item:has(+ [data-tour-current]):active,
.nb-item[data-tour-current] + .nb-item:active {
  transform: scale(0.92);
}

/* the arrow's own name is the label of the room it leads to — hide it,
   the chevron says enough */
.nb-item:has(+ [data-tour-current]) .nb-name,
.nb-item[data-tour-current] + .nb-item .nb-name {
  display: none;
}

/* chevrons, drawn from two borders */
.nb-item:has(+ [data-tour-current])::before,
.nb-item[data-tour-current] + .nb-item::before {
  content: "";
  width: 9px;
  height: 9px;
  border-top: 2px solid currentColor;
  border-right: 2px solid currentColor;
  border-radius: 1px;
}
.nb-item:has(+ [data-tour-current])::before {
  transform: translateX(2px) rotate(-135deg);
}
.nb-item[data-tour-current] + .nb-item::before {
  transform: translateX(-2px) rotate(45deg);
}

/* ---- tablet ----------------------------------------------------------- */
@media (max-width: 1100px) {
  /* the bar reaches the pill — drop the words, keep the "i" */
  .ip-open { padding: 0; width: 40px; justify-content: center; }
  .ip-open-text { display: none; }
  .ip-open-mark { width: 28px; height: 28px; font-size: 14px; }
}

@media (max-width: 860px) {
  .tm { gap: 12px; padding-left: 16px; }
  .tm-btn { padding: 7px 11px; }
  .tm-panel-scenes { grid-template-columns: repeat(2, 132px); }
}

/* ---- phones: the bar becomes one drop-down ---------------------------- */
@media (max-width: 640px) {
  .tm {
    top: calc(10px + env(safe-area-inset-top, 0px));
    gap: 10px;
    width: calc(100vw - 20px);
    max-width: 420px;
    padding: 7px 7px 7px 16px;
    justify-content: space-between;
  }

  .tm-brand {
    display: block;
    min-width: 0;
    font-size: 13px;
  }

  /* the hamburger */
  .tm-burger {
    display: grid;
    place-content: center;
    gap: 4px;
    flex: none;
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.14);
    cursor: pointer;
    transition: background-color 0.15s ease-out;
    -webkit-tap-highlight-color: transparent;
  }
  .tm-burger:active { background: rgba(255, 255, 255, 0.26); }
  .tm-burger span {
    display: block;
    width: 16px;
    height: 2px;
    border-radius: 2px;
    background: currentColor;
    transition: transform 0.18s ease-out, opacity 0.12s ease-out;
  }

  /* open state: the bars become a cross */
  .tm-toggle:checked ~ .tm-burger { background: rgba(255, 255, 255, 0.26); }
  .tm-toggle:checked ~ .tm-burger span:nth-child(1) { transform: translateY(6px) rotate(45deg); }
  .tm-toggle:checked ~ .tm-burger span:nth-child(2) { opacity: 0; }
  .tm-toggle:checked ~ .tm-burger span:nth-child(3) { transform: translateY(-6px) rotate(-45deg); }

  /* the drop-down itself: every section stacked in one scrolling sheet */
  .tm-nav {
    position: absolute;
    top: calc(100% + 10px);
    left: 0;
    right: 0;
    display: block;
    box-sizing: border-box;
    max-height: calc(100vh - 150px - env(safe-area-inset-top, 0px));
    max-height: calc(100dvh - 150px - env(safe-area-inset-top, 0px));
    padding: 8px;
    border-radius: 20px;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;

    opacity: 0;
    visibility: hidden;
    transform: translateY(-8px);
    transition: opacity 0.18s ease-out, transform 0.18s ease-out, visibility 0.18s;

    background: rgba(20, 22, 28, 0.55);
    border: 1px solid rgba(255, 255, 255, 0.18);
    backdrop-filter: blur(22px) saturate(160%);
    -webkit-backdrop-filter: blur(22px) saturate(160%);
    box-shadow:
      0 16px 40px rgba(0, 0, 0, 0.44),
      inset 0 1px 0 rgba(255, 255, 255, 0.22);
  }
  .tm-toggle:checked ~ .tm-nav {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }

  /* sections read as headed lists, not as nested menus */
  .tm-group + .tm-group {
    margin-top: 6px;
    padding-top: 6px;
    border-top: 1px solid rgba(255, 255, 255, 0.12);
  }

  .tm-btn {
    width: 100%;
    padding: 6px 8px;
    border-radius: 8px;
    text-align: left;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.55);
    pointer-events: none;
  }
  .tm-btn:hover,
  .tm-group:focus-within .tm-btn { background: transparent; }

  /* panels stop being panels — they sit in the flow of the sheet */
  .tm-panel,
  .tm-group:hover .tm-panel,
  .tm-group:focus-within .tm-panel {
    position: static;
    transform: none;
    width: auto;
    padding: 0 4px 4px;
    opacity: 1;
    visibility: visible;
    background: none;
    border: 0;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    box-shadow: none;
    transition: none;
  }
  .tm-panel::before { display: none; }

  /* scenes: a list of rows, thumb beside the name */
  .tm-panel-scenes {
    display: block;
    max-height: none;
    overflow: visible;
  }
  .tm-scene {
    flex-direction: row;
    align-items: center;
    gap: 10px;
    width: 100%;
    padding: 6px 8px;
    font-size: 13px;
  }
  .tm-scene + .tm-scene { margin-top: 2px; }
  .tm-scene-thumb {
    flex: none;
    width: 54px;
    border-radius: 5px;
  }
  .tm-scene-name { min-width: 0; }

  .tm-panel-text { font-size: 12.5px; }
  .tm-panel-text h3 { display: none; }

  /* ---- the info sidebar on phones -----------------------------------
     The bar owns the top of the screen, so the pill sits down beside the
     bottom nav, and the sidebar comes up as a sheet from the bottom. */
  .ip-open {
    top: auto;
    right: 12px;
    bottom: calc(16px + env(safe-area-inset-bottom, 0px));
    width: 44px;
    height: 44px;
  }
  .ip-toggle:checked ~ .ip-open { transform: translateY(12px); }

  .ip {
    top: auto;
    right: 10px;
    left: 10px;
    bottom: calc(10px + env(safe-area-inset-bottom, 0px));
    width: auto;
    max-height: 62vh;
    max-height: 62dvh;
    padding: 20px;
    transform: translateY(18px);
  }
  .ip-toggle:checked ~ .ip { transform: translateY(0); }

  .ip-name { font-size: 17px; }
  .ip-text { font-size: 13px; }

  /* ---- bottom bar stays inside the screen ---------------------------- */
  .nb {
    bottom: calc(14px + env(safe-area-inset-bottom, 0px));
    max-width: calc(100vw - 20px);
    font-size: 12px;
  }
  .nb-track {
    width: min(320px, calc(100vw - 20px));
    height: 48px;
    padding: 0 50px;
  }
}

/* ---- very small phones ------------------------------------------------ */
@media (max-width: 380px) {
  .tm { padding-left: 13px; gap: 8px; }
  .tm-brand { font-size: 12px; }

  .nb-track {
    width: calc(100vw - 20px);
    height: 44px;
    padding: 0 46px;
  }
  .nb-item:has(+ [data-tour-current]),
  .nb-item[data-tour-current] + .nb-item {
    width: 32px;
    height: 32px;
    margin-top: -16px;
  }

  /* the nav pill and the info button share the row */
  .ip-open { width: 40px; height: 40px; bottom: calc(12px + env(safe-area-inset-bottom, 0px)); }
}

/* ---- short / landscape phones ----------------------------------------- */
@media (max-height: 460px) and (max-width: 900px) {
  .tm { top: calc(8px + env(safe-area-inset-top, 0px)); }
  .tm-nav { max-height: calc(100vh - 90px); max-height: calc(100dvh - 90px); }
  .nb { bottom: calc(10px + env(safe-area-inset-bottom, 0px)); }
  .nb-track { height: 44px; }

  .ip {
    top: calc(8px + env(safe-area-inset-top, 0px));
    left: auto;
    right: 10px;
    bottom: 10px;
    width: min(340px, calc(100vw - 20px));
    max-height: none;
    padding: 16px 18px;
    transform: translateX(16px);
  }
  .ip-toggle:checked ~ .ip { transform: translateX(0); }
}
